import json

CLIENT_CAPABILITIES = {"resources", "prompts", "elicitation"}
SERVER_CAPABILITIES = {"tools", "resources", "prompts", "notifications"}
TYPE_CHECKS = {
    "string": lambda value: isinstance(value, str),
    "integer": lambda value: type(value) is int,
    "number": lambda value: type(value) in (int, float),
    "boolean": lambda value: type(value) is bool,
}


def load_json(filename):
    with open(filename, "r", encoding="utf-8") as handle:
        return json.load(handle)


def validate_capabilities(value, expected_keys, name):
    if not isinstance(value, dict):
        return [name + " must be an object"]
    errors = []
    if set(value) != expected_keys:
        errors.append(name + " must contain exactly " + ", ".join(sorted(expected_keys)))
    if not all(type(flag) is bool for flag in value.values()):
        errors.append(name + " values must be Boolean")
    return errors


def validate_schema(schema, prefix):
    if not isinstance(schema, dict):
        return [prefix + " must be an object"]
    errors = []
    for key, type_name in schema.items():
        if not isinstance(key, str) or not key:
            errors.append(prefix + " keys must be non-empty strings")
        # Check the value's primitive shape before dictionary membership. This
        # prevents None, list, dict, Boolean, and number values from raising.
        if not isinstance(type_name, str):
            errors.append(prefix + " type names must be strings")
        elif type_name not in TYPE_CHECKS:
            errors.append(prefix + " has unsupported input type: " + type_name)
    return errors


def validate_inventory(inv):
    if not isinstance(inv, dict):
        return ["inventory must be an object"]

    errors = []
    if inv.get("protocol_version") != "2026-07-28":
        errors.append("protocol_version must be 2026-07-28")

    errors.extend(validate_capabilities(
        inv.get("client_capabilities"), CLIENT_CAPABILITIES,
        "client_capabilities"))
    errors.extend(validate_capabilities(
        inv.get("server_capabilities"), SERVER_CAPABILITIES,
        "server_capabilities"))

    all_ids = []
    valid_groups = {}
    for group in ("tools", "resources", "prompts"):
        items = inv.get(group)
        if not isinstance(items, list):
            errors.append(group + " must be a list")
            valid_groups[group] = []
            continue
        valid_groups[group] = items
        for index, item in enumerate(items):
            prefix = group + "[" + str(index) + "]"
            if not isinstance(item, dict):
                errors.append(prefix + " must be an object")
                continue

            item_id = item.get("id")
            if not isinstance(item_id, str) or not item_id:
                errors.append(prefix + " id must be a non-empty string")
            else:
                all_ids.append(item_id)

            if item.get("kind") != group[:-1]:
                errors.append(prefix + " has incorrect primitive classification")

            if group == "tools":
                errors.extend(validate_schema(item.get("input"), prefix + " input"))
                annotation = item.get("annotation")
                if not isinstance(annotation, dict):
                    errors.append(prefix + " annotation must be an object")
                elif type(annotation.get("readOnly")) is not bool:
                    errors.append(prefix + " annotation.readOnly must be Boolean")
                if not isinstance(item.get("access"), str):
                    errors.append(prefix + " access claim must be a string")
            elif group == "resources":
                if not isinstance(item.get("data_class"), str):
                    errors.append(prefix + " data_class must be a string")
            else:
                if not isinstance(item.get("review"), str):
                    errors.append(prefix + " review must be a string")

    if len(all_ids) != len(set(all_ids)):
        errors.append("duplicate primitive ID")

    server_caps = inv.get("server_capabilities")
    if isinstance(server_caps, dict):
        for group in ("tools", "resources", "prompts"):
            if valid_groups.get(group) and server_caps.get(group) is not True:
                errors.append(group + " are present while their server capability is not true")

    return errors


def validate_string_allowlist(value, name):
    if not isinstance(value, list):
        return [name + " must be a list"]
    errors = []
    for index, item in enumerate(value):
        if not isinstance(item, str) or not item:
            errors.append(name + "[" + str(index) + "] must be a non-empty string")
    if all(isinstance(item, str) and item for item in value):
        if len(value) != len(set(value)):
            errors.append(name + " contains duplicate IDs")
    return errors


def validate_policy(policy):
    if not isinstance(policy, dict):
        return ["policy must be an object"]

    errors = []
    if policy.get("protocol_version") != "2026-07-28":
        errors.append("policy protocol_version must be 2026-07-28")
    errors.extend(validate_capabilities(
        policy.get("supported_server_capabilities"), SERVER_CAPABILITIES,
        "supported_server_capabilities"))

    tools = policy.get("tools")
    if not isinstance(tools, dict):
        errors.append("policy tools must be an object")
    else:
        for tool_id, entry in tools.items():
            prefix = "policy tools[" + repr(tool_id) + "]"
            if not isinstance(tool_id, str) or not tool_id:
                errors.append("policy tool IDs must be non-empty strings")
            if not isinstance(entry, dict):
                errors.append(prefix + " must be an object")
                continue
            if entry.get("mode") not in ("read", "write"):
                errors.append(prefix + " mode must be read or write")
            errors.extend(validate_schema(entry.get("input"), prefix + " input"))
            claims = entry.get("reviewed_claims")
            if not isinstance(claims, dict):
                errors.append(prefix + " reviewed_claims must be an object")
            else:
                if not isinstance(claims.get("access"), str):
                    errors.append(prefix + " reviewed_claims.access must be a string")
                annotation = claims.get("annotation")
                if not isinstance(annotation, dict):
                    errors.append(prefix + " reviewed_claims.annotation must be an object")
                elif type(annotation.get("readOnly")) is not bool:
                    errors.append(prefix + " reviewed_claims.annotation.readOnly must be Boolean")

    errors.extend(validate_string_allowlist(policy.get("resources"), "policy resources"))
    errors.extend(validate_string_allowlist(policy.get("prompts"), "policy prompts"))
    return errors


def review_inventory(inv, policy):
    errors = validate_inventory(inv) + validate_policy(policy)
    if errors:
        return errors

    supported = policy["supported_server_capabilities"]
    for capability, advertised in inv["server_capabilities"].items():
        if advertised is True and supported.get(capability) is not True:
            errors.append("unsupported server capability: " + capability)

    for tool in inv["tools"]:
        tool_id = tool["id"]
        trusted = policy["tools"].get(tool_id)
        if not isinstance(trusted, dict):
            errors.append("unreviewed tool: " + tool_id)
            continue
        if trusted.get("input") != tool.get("input"):
            errors.append("input schema changed since trusted review: " + tool_id)
        observed_claims = {
            "access": tool.get("access"),
            "annotation": tool.get("annotation"),
        }
        if trusted.get("reviewed_claims") != observed_claims:
            errors.append("inventory claims changed since trusted review: " + tool_id)

    allowed_resources = set(policy["resources"])
    for resource in inv["resources"]:
        if resource["id"] not in allowed_resources:
            errors.append("unreviewed resource: " + resource["id"])

    allowed_prompts = set(policy["prompts"])
    for prompt in inv["prompts"]:
        if prompt["id"] not in allowed_prompts:
            errors.append("unreviewed prompt: " + prompt["id"])

    return errors


def trusted_mode(policy, tool_id):
    if not isinstance(policy, dict) or not isinstance(policy.get("tools"), dict):
        return None
    entry = policy["tools"].get(tool_id)
    if not isinstance(entry, dict):
        return None
    return entry.get("mode")


def host_request(inv, policy, tool_id, arguments, approval=False):
    if type(approval) is not bool:
        return "REJECT: approval must be Boolean"
    if not isinstance(arguments, dict):
        return "REJECT: arguments must be an object"

    review_errors = review_inventory(inv, policy)
    if review_errors:
        return "REJECT: " + review_errors[0]

    tool = next((item for item in inv["tools"] if item["id"] == tool_id), None)
    if tool is None:
        return "REJECT: unsupported tool"

    trusted = policy["tools"].get(tool_id)
    if not isinstance(trusted, dict):
        return "REJECT: unreviewed tool"
    schema = trusted.get("input")
    if not isinstance(schema, dict):
        return "REJECT: invalid trusted input schema"

    if set(arguments) != set(schema):
        return "REJECT: arguments must contain exactly the required keys"
    for key, type_name in schema.items():
        check = TYPE_CHECKS.get(type_name)
        if check is None or not check(arguments[key]):
            return "REJECT: wrong argument type for " + key

    mode = trusted.get("mode")
    if mode == "write":
        if approval is not True:
            return "REJECT: write requires host approval"
        return "ACCEPT: approved write teaching request"
    if mode == "read":
        return "ACCEPT: read-only teaching request"
    return "REJECT: unknown trusted tool policy"
